import{_ as l,r as t,o as p,c,e as o,a as e,s as n,d as s}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Development Workflow - October CMS - 4.x","titleTemplate":false,"description":"Learn how to manage your October CMS project with Git and keep environments in sync.","frontmatter":{"subtitle":"Learn how to manage your October CMS project with Git and keep environments in sync."},"headers":[{"level":2,"title":"Repository Strategies","slug":"repository-strategies","link":"#repository-strategies","children":[{"level":3,"title":"Monolith Repository","slug":"monolith-repository","link":"#monolith-repository","children":[]},{"level":3,"title":"Modular Repositories","slug":"modular-repositories","link":"#modular-repositories","children":[]}]},{"level":2,"title":"Installing Packages from Git","slug":"installing-packages-from-git","link":"#installing-packages-from-git","children":[]},{"level":2,"title":"Synchronizing with the Server","slug":"synchronizing-with-the-server","link":"#synchronizing-with-the-server","children":[]},{"level":2,"title":"Recommended Workflow","slug":"recommended-workflow","link":"#recommended-workflow","children":[{"level":3,"title":"Automated Deployments","slug":"automated-deployments","link":"#automated-deployments","children":[]}]},{"level":2,"title":"Working with the Backend Editor","slug":"working-with-the-backend-editor","link":"#working-with-the-backend-editor","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/resources/development-workflow.md","filePath":"4.x/resources/development-workflow.md"}'),d={name:"4.x/resources/development-workflow.md"};function h(g,a,m,u,k,v){const r=t("pre-heading"),i=t("post-heading");return p(),c("div",null,[o(r),a[0]||(a[0]=e("h1",null,"Development Workflow",-1)),o(i),a[1]||(a[1]=n(`<p>October CMS projects can be managed using different Git strategies depending on the size and complexity of your site. This article covers recommended workflows for local development, version control, and server synchronization.</p><h2 id="repository-strategies"><a href="#repository-strategies" class="header-anchor">#</a> Repository Strategies</h2><p>There are two primary approaches to structuring your Git repositories.</p><h3 id="monolith-repository"><a href="#monolith-repository" class="header-anchor">#</a> Monolith Repository</h3><p>For smaller sites, a single Git repository containing the entire project is the simplest approach. This keeps everything in one place and is easy to manage.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token comment"># Clone the entire project</span>
<span class="token function">git</span> clone git@github.com:yourorg/myproject.git
</code></pre></div><p>Use a <code>.gitignore</code> file to exclude vendor packages and core modules that are managed by Composer.</p><div class="language-gitignore extra-class"><pre class="language-gitignore"><code><span class="token entry string"><span class="token punctuation">/</span>vendor</span>
<span class="token entry string"><span class="token punctuation">/</span>modules</span>
<span class="token entry string"><span class="token punctuation">/</span>plugins<span class="token punctuation">/</span><span class="token operator">*</span><span class="token punctuation">/</span><span class="token operator">*</span></span>
<span class="token entry string"><span class="token operator">!</span><span class="token punctuation">/</span>plugins<span class="token punctuation">/</span>yourcompany</span>
<span class="token entry string"><span class="token punctuation">/</span>themes<span class="token punctuation">/</span><span class="token operator">*</span></span>
<span class="token entry string"><span class="token operator">!</span><span class="token punctuation">/</span>themes<span class="token punctuation">/</span>yourtheme</span>
</code></pre></div><p>This approach tracks only your custom code while letting Composer manage dependencies.</p><h3 id="modular-repositories"><a href="#modular-repositories" class="header-anchor">#</a> Modular Repositories</h3><p>For larger sites, each in-house plugin and theme can be its own Git repository. This provides better separation of concerns and allows different team members to work on different packages independently.</p><div class="language- extra-class"><pre class="language-text"><code>plugins/
├── acme/
│   └── blog/          ← Separate Git repo
├── acme/
│   └── shop/          ← Separate Git repo
themes/
└── mycompany-theme/   ← Separate Git repo
</code></pre></div><p>Both strategies are compatible with each other. You can have a monolith repository that contains submodules, or manage packages entirely independently.</p><h2 id="installing-packages-from-git"><a href="#installing-packages-from-git" class="header-anchor">#</a> Installing Packages from Git</h2><p>Plugins and themes can be installed directly from a Git repository using Composer.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan plugin:install Acme.Blog <span class="token parameter variable">--from</span><span class="token operator">=</span>git@github.com:acme/blog-plugin.git
</code></pre></div><p>Use the <code>--want</code> option to specify a branch or version.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan plugin:install Acme.Blog <span class="token parameter variable">--from</span><span class="token operator">=</span>git@github.com:acme/blog-plugin.git <span class="token parameter variable">--want</span><span class="token operator">=</span>dev-develop
</code></pre></div><p>The same applies to themes.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:install acme-starter <span class="token parameter variable">--from</span><span class="token operator">=</span>git@github.com:acme/starter-theme.git
</code></pre></div><div class="custom-block tip"><p>Use the <code>--oc</code> option if the repository name has the <code>oc-</code> prefix convention, for example <code>oc-blog-plugin</code>.</p></div><h2 id="synchronizing-with-the-server"><a href="#synchronizing-with-the-server" class="header-anchor">#</a> Synchronizing with the Server</h2><p>When working with modular repositories, you can pull updates for all Git-managed packages at once using the utility command.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan october:util <span class="token function">git</span> pull
</code></pre></div><p>This command iterates through all plugins and themes that are Git repositories and pulls the latest changes from their remotes.</p><p>For individual packages, navigate to the package directory and use standard Git commands.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token builtin class-name">cd</span> plugins/acme/blog
<span class="token function">git</span> pull origin main
</code></pre></div><p>After pulling changes, run migrations to apply any database updates.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan october:migrate
</code></pre></div><h2 id="recommended-workflow"><a href="#recommended-workflow" class="header-anchor">#</a> Recommended Workflow</h2><p>A typical development workflow looks like this.</p><ol><li><strong>Develop locally</strong> using your preferred IDE</li><li><strong>Commit changes</strong> to your Git repository</li><li><strong>Push to remote</strong> (GitHub, GitLab, Bitbucket, etc.)</li><li><strong>Pull on server</strong> via SSH using <code>git pull</code> or <code>october:util git pull</code></li><li><strong>Run migrations</strong> with <code>php artisan october:migrate</code></li></ol><h3 id="automated-deployments"><a href="#automated-deployments" class="header-anchor">#</a> Automated Deployments</h3><p>For more automated workflows, consider these options.</p>`,34)),a[2]||(a[2]=e("ul",null,[e("li",null,[e("strong",null,"CI/CD pipelines"),s(" that deploy on push to specific branches")]),e("li",null,[e("strong",null,"Git hooks"),s(" on the server that pull changes automatically")]),e("li",null,[e("strong",null,[e("a",{href:"https://octobercms.com/plugin/rainlab-deploy",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("Deploy Plugin"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),e("span",{class:"sr-only"},"(opens new window)")])])]),s(" for environments without SSH access")])],-1)),a[3]||(a[3]=n('<h2 id="working-with-the-backend-editor"><a href="#working-with-the-backend-editor" class="header-anchor">#</a> Working with the Backend Editor</h2><p>The backend CMS editor saves changes directly to the theme files on the server filesystem. When using Git:</p><ul><li>Changes made in the backend editor exist only on the server until committed</li><li>Pull these changes to your local environment before making local edits</li><li>Consider using <a href="./../cms/themes/database-themes.html">database themes</a> if multiple editors need to work simultaneously</li></ul><p>For teams where content editors use the backend while developers use local files, establish a clear workflow to avoid conflicts. One approach is to have editors work on a staging server, with changes reviewed and merged into the main repository periodically.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./installing-packages.html">Installing Plugins &amp; Themes</a></li><li><a href="./../setup/deployment.html">Deployment</a></li><li><a href="./../cms/themes/database-themes.html">Database Themes</a></li></ul></div>',6))])}const w=l(d,[["render",h]]);export{f as __pageData,w as default};
